Item.method_code:
const supportedDataType = ['integer', 'text', 'string', 'float', 'date', 'boolean', 'decimal'];
const item = aras.itemsCache.getItemByXPath("//Item[@id='"+itemId+"']");
const dataType = name === 'data_type' ? value : aras.getItemProperty(item,'data_type');
const isFederated = name === 'is_federated' ? value ? "1" : "0" : aras.getItemProperty(item, 'is_federated');

const result = {
    valid : true
};

if(dataType && isFederated === "1" && !supportedDataType.includes(dataType))
{
    result.valid = false;
    result.validationMessage = aras.getResource('', 'ui_methods_ex.property_datatype_for_federated_not_supported', dataType);
}

return result;
